{"implementation":"def solve(case):
    data = case.get("payload", case)
    nodes = list(data["nodes"])
    core = data["core_distance"]
    order = {node: i for i, node in enumerate(nodes)}

    edges = []
    for position, item in enumerate(data["distances"]):
        u, v, distance = item
        weight = max(distance, core[u], core[v])
        if order[u] <= order[v]:
            a, b = u, v
        else:
            a, b = v, u
        edges.append((weight, order[a], order[b], position, a, b))

    edges.sort(key=lambda edge: edge[:4])
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    mst = []
    total_weight = 0.0
    for weight, _, _, _, u, v in edges:
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            continue
        if rank[root_u] < rank[root_v]:
            root_u, root_v = root_v, root_u
        parent[root_v] = root_u
        if rank[root_u] == rank[root_v]:
            rank[root_u] += 1
        mst.append([u, v, weight])
        total_weight += weight
        if len(mst) == max(0, len(nodes) - 1):
            break

    return {"mst_edges": mst, "total_weight": total_weight}
"}
